public class StringCreationDemo {
    public static void main(String[] args) {
        // 1. String Literals (Reused from String Pool)
        String s1 = "LearnBySelf";
        String s2 = "LearnBySelf";

        // 2. new Keyword (Forced new object in regular Heap)
        String s3 = new String("LearnBySelf");

        // Output references comparison (memory address check)
        System.out.println("s1 == s2: " + (s1 == s2)); // true
        System.out.println("s1 == s3: " + (s1 == s3)); // false

        // Content comparison (character sequence check)
        System.out.println("s1.equals(s3): " + s1.equals(s3)); // true

        // Checking identity hash codes to observe physical memory difference
        System.out.println("s1 Hash: " + System.identityHashCode(s1));
        System.out.println("s2 Hash: " + System.identityHashCode(s2));
        System.out.println("s3 Hash: " + System.identityHashCode(s3));
    }
}

