practiceProblems.solutionCode:
public class SubstringComparison {
    public static void main(String[] args) {
        String message = "Backend Engineer";
        String target = "Engineer";
        String extracted = message.substring(8);
        System.out.println("Extracted: " + extracted);
        System.out.println("Content equals: " + extracted.equals(target));
        System.out.println("Same reference: " + (extracted == target));
    }
}

